// Sleep stages algorithm processing status.
type Sleep_SleepMetadata_StagesState int32

const (
	// Output only. Sleep stages status is unspecified.
	Sleep_SleepMetadata_STAGES_STATE_UNSPECIFIED Sleep_SleepMetadata_StagesState = 0
	// Output only. Sleep stages cannot be computed due to low RR coverage.
	Sleep_SleepMetadata_REJECTED_COVERAGE Sleep_SleepMetadata_StagesState = 1
	// Output only. Sleep stages cannot be computed due to the large middle
	// gap (2h).
	Sleep_SleepMetadata_REJECTED_MAX_GAP Sleep_SleepMetadata_StagesState = 2
	// Output only. Sleep stages cannot be computed due to the large start
	// gap (1h).
	Sleep_SleepMetadata_REJECTED_START_GAP Sleep_SleepMetadata_StagesState = 3
	// Output only. Sleep stages cannot be computed due to the large end gap
	// (1h).
	Sleep_SleepMetadata_REJECTED_END_GAP Sleep_SleepMetadata_StagesState = 4
	// Output only. Sleep stages cannot be computed because the sleep log is a
	// nap (has < 3h duration).
	Sleep_SleepMetadata_REJECTED_NAP Sleep_SleepMetadata_StagesState = 5
	// Output only. Sleep stages cannot be computed because input data is not
	// available (PPGV2, wake magnitude, etc).
	Sleep_SleepMetadata_REJECTED_SERVER Sleep_SleepMetadata_StagesState = 6
	// Output only. Sleep stages cannot be computed due to server timeout.
	Sleep_SleepMetadata_TIMEOUT Sleep_SleepMetadata_StagesState = 7
	// Output only. Sleep stages successfully computed.
	Sleep_SleepMetadata_SUCCEEDED Sleep_SleepMetadata_StagesState = 8
	// Output only. Sleep stages cannot be computed due to server internal
	// error.
	Sleep_SleepMetadata_PROCESSING_INTERNAL_ERROR Sleep_SleepMetadata_StagesState = 9
)

